sys_script_include.script:
var LicenseAPI = Class.create();
LicenseAPI.CONSTANTS = {
    INT_MAP: {
        GET: {
            path: "/apps/licensing/v1/product/${productId}/sku/${skuId}/user/${userId}",
            httpMethod: "GET",
            pathParams: ["productId", "skuId", "userId"],
            aliasId: "150209ddeb87ba105c06fcffcad0cd42"
        }
    }
};
LicenseAPI.prototype = {
    initialize: function() {},

    ensureToken: function() {
        const context = "x_neyu_rest_utils_oauth_credentials";
        const requestor = gs.getProperty("x_neyu_google_nyu.license.api.credential.id");
        (new global.OAuthTokenGetter()).processJWT(
            requestor,
            context,
            "8491b701ebcf7a105c06fcffcad0cda8", // Google Licensing API
            "3b683f45ebcf7a105c06fcffcad0cd99" // Google Licensing API default_profile
        );
    },

    get: function(productId, skuId, userId) {
        if (!productId || !skuId || !userId) {
            return {
                error: true,
                errorMessage: "There were missing parameters"
            };
        }

        this.ensureToken();

        const pathParams = {
            productId: productId,
            skuId: skuId,
            userId: userId
        };
        const config = LicenseAPI.CONSTANTS.INT_MAP.GET;
        const requestConfig = {
            ...config,
            pathParams
        };

        const builder = new x_neyu_rest_utils.RequestBuilder(requestConfig);
        const api = new x_neyu_rest_utils.WebServiceUtil();

        let response;
        try {
            response = api.executeRestMessage(builder.build());
        } catch (ex) {
            gs.error("[get] there was an internal error building and executing" +
                " the RestMessage.\nError: " + ex);
            return {
                error: true,
                errorMessage: ex + ""
            };
        }

        if (response.error) {
            gs.error("[get] There was an error returned from the Google API." +
                "\nError: " + response.errorMessage);
        }

        // gs.info("[get] Response: " + JSON.stringify(response));
        return {
            ...response,
            error: response.status != 200,
            errorMessage: (
                response.status != 200 ?
                response.responseBody : response.errorMessage
            )
        };
    },

    type: 'LicenseAPI'
};
